# Tạo list scores = [9, 7, 10, 8, 6]
scores = [9, 7, 10, 8, 6]                                                                                                                                                                                                        
                                                                                                                                                                                                        
# In ra điểm cao nhất
print(scores[2])                                                                                                                                                                                                     
                                                                                                                                                                                                        
# Tính điểm trung bình
# print(len(scores))
# print(sum(scores)) 
print(sum(scores)/len(scores))                                                                                                                                                                                                
                                                                                                                                                                                                        
# Thêm điểm 5 vào cuối list
scores.append(5)
print(scores)                                                                                                                                                                                                
                                                                                                                                                                                                        
# Tạo tuple birthday = (11, 9, 2025) → in ra ngày, tháng, năm. 
